/**
 * Normalized card records. Generated by `npm run cards:update` from optcgapi.com (ADR 0007),
 * repaired by the normalizer and by hand-verified overrides in `cards/overrides/`. Never hand-edited.
 */
export type CardCategory = 'Leader' | 'Character' | 'Event' | 'Stage';
export type Color = 'Red' | 'Green' | 'Blue' | 'Purple' | 'Black' | 'Yellow';
export type Attribute = 'Slash' | 'Strike' | 'Ranged' | 'Special' | 'Wisdom';

/** Printed keyword abilities (CR 10-1), excluding [Trigger], which has its own field. */
export type Keyword =
  'Rush' | 'Rush: Character' | 'Double Attack' | 'Banish' | 'Blocker' | 'Unblockable';

/** Block number printed on the card (topics/013.php). `X` marks Super Parallel Rare numbers. */
export type Block = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 'X';

/** Image sources known to the app's art module. The base URL of each lives only in `app/src/art/`. */
export type ImageSource = 'optcgapi';

export interface Artwork {
  /**
   * Printing id. The base printing uses the bare card id; alternates keep the upstream suffix
   * (`OP17-005_p1`). When upstream reuses one id for different art, later ones get `#2`, `#3`.
   */
  artworkId: string;
  /**
   * Image paths **relative to the source's base URL** (the art module owns the base, so a source can be
   * swapped in one place). optcgapi serves one size, 600 x 838, as `full`.
   */
  imageUrls: { full?: string };
  source: ImageSource;
  /** Product code the printing came from upstream, such as `OP-17`, `PRB-02` or `P`. */
  product: string;
  rarity: string;
  /** Upstream's printing label, such as "Alternate Art" or "Treasure Cup August 2025". */
  label?: string;
}

/** How a card number stands in one format. */
export interface Legality {
  status: 'legal' | 'banned' | 'restricted' | 'rotated' | 'unknown';
  /** Copy limit when restricted. */
  limit?: number;
  /** Banned pairs: card numbers this card may not share a deck with. */
  bannedWith?: string[];
  /** Short reason, e.g. "block 1", "SPR exception", "banned 2026-10-12". */
  reason?: string;
}

export type CardField =
  | 'name'
  | 'effectText'
  | 'triggerText'
  | 'cost'
  | 'power'
  | 'counter'
  | 'life'
  | 'colors'
  | 'attributes'
  | 'types'
  | 'category';

/** One audited change to upstream text or data. */
export interface TextFix {
  field: CardField;
  /**
   * `sign`: a dropped minus sign restored by the normalizer rule.
   * `cleanup`: junk removed (reprint disclaimers, upstream notes, NULL text).
   * `trigger`: a [Trigger] marker restored.
   * `override`: a hand-verified correction from `cards/overrides/`.
   */
  kind: 'sign' | 'cleanup' | 'trigger' | 'override';
  from: string;
  to: string;
  /** Where the correction is confirmed (overrides only). */
  source?: string;
}

export interface VerificationSource {
  url: string;
  /** ISO date the source was read. */
  date: string;
  /** What the source was used for. */
  use: 'cross-check' | 'disagreement' | 'format';
}

export interface Card {
  /** Card number, shared by every printing: `OP17-005`. */
  id: string;
  name: string;
  category: CardCategory;
  colors: Color[];
  /** Play cost; null for Leaders. */
  cost: number | null;
  /** Null for Events and Stages. */
  power: number | null;
  /** Counter value; null when the card has none. */
  counter: number | null;
  /** Leaders only. */
  life: number | null;
  attributes: Attribute[];
  types: string[];
  rarity: string;
  /** Product code of the card number: `OP-17`, `ST-01`, `EB-04`, `PRB-01` or `P`. */
  set: string;
  /** Block number from `cards/format/standard.json`; null when no cited source gives it. */
  block: Block | null;
  /** Effect text without the trigger. Empty for vanilla cards. */
  effectText: string;
  /** Trigger text without the leading "[Trigger]"; null when the card has none. */
  triggerText: string | null;
  /** Printed keywords, only from a verified override (effect-dsl E-D7); never parsed into play. */
  keywords: Keyword[];
  /** True when every game field was checked by a person against cited sources. */
  verified: boolean;
  verifiedBy: VerificationSource[];
  textFixes: TextFix[];
  /** Optional art-window focus (percent of the scan) where the default crop misses the subject. */
  artFocus?: { x: number; y: number };
  artworks: Artwork[];
  legality: { standard: Legality; extra: Legality };
  /** Upstream record for this card number. */
  sourceUrl: string;
  fetchedAt: string;
}

export interface SetSummary {
  /** `OP-17`, `ST-01`, `EB-04`, `PRB-01` or `P`. */
  code: string;
  name: string;
  kind: 'booster' | 'starter' | 'extra' | 'premium' | 'promo';
  cardCount: number;
  block: Block | null;
}

export interface SetFile {
  set: SetSummary;
  cards: Card[];
}

export interface Manifest {
  source: string;
  sourceUrl: string;
  /** When upstream data was fetched (newest cache file). */
  fetchedAt: string;
  generatedAt: string;
  cardCount: number;
  printingCount: number;
  newestSet: string;
  verifiedCount: number;
  sets: SetSummary[];
  /** Repairs made by the normalizer and overrides, by class. */
  repairs: Record<string, number>;
}
